/* com.portal.board.bbs.BBSManageMapper.selectMaxNttId */
SELECT IFNULL(MAX(NTT_ID), 0) + 1 AS NTT_ID
  FROM LETTNBBS

mapper.insert:
/* com.portal.board.bbs.BBSManageMapper.insertBoardArticle */
SELECT IFNULL(MAX(SORT_ORDR), 0) + 1 AS NTT_NO FROM LETTNBBS WHERE BBS_ID = #{bbsId}
INSERT INTO LETTNBBS ( NTT_ID, BBS_ID, NTT_SJ, NTT_CN, SORT_ORDR, NTCR_ID, NTCR_NM, PASSWORD, RDCNT, NTCE_BGNDE, NTCE_ENDDE, ANSWER_AT, PARNTSCTT_NO, NTT_NO, ANSWER_LC, ATCH_FILE_ID, FRST_REGISTER_ID, FRST_REGIST_PNTTM, USE_AT ) VALUES ( #{nttId}, #{bbsId}, #{nttSj}, #{nttCn}, #{sortOrdr}, #{ntcrId}, #{ntcrNm}, #{password}, #{inqireCo}, #{ntceBgnde}, #{ntceEndde}, #{replyAt}, #{parnts}, 1, #{replyLc}, #{atchFileId}, #{frstRegisterId}, SYSDATE(), 'Y' )

/* com.portal.board.bbs.BBSManageMapper.replyBoardArticle */
SELECT IFNULL(MAX(NTT_NO), 0) + 1 AS NTT_NO FROM LETTNBBS WHERE BBS_ID = #{bbsId} AND SORT_ORDR = #{sortOrdr}
INSERT INTO LETTNBBS ( NTT_ID, BBS_ID, NTT_SJ, NTT_CN, SORT_ORDR, NTCR_ID, NTCR_NM, PASSWORD, RDCNT, NTCE_BGNDE, NTCE_ENDDE, ANSWER_AT, PARNTSCTT_NO, NTT_NO, ANSWER_LC, ATCH_FILE_ID, FRST_REGISTER_ID, FRST_REGIST_PNTTM, USE_AT ) VALUES ( #{nttId}, #{bbsId}, #{nttSj}, #{nttCn}, #{sortOrdr}, #{ntcrId}, #{ntcrNm}, #{password}, #{inqireCo}, #{ntceBgnde}, #{ntceEndde}, #{replyAt}, #{parnts}, 1, #{replyLc}, #{atchFileId}, #{frstRegisterId}, SYSDATE(), 'Y' )

mapper.select:
/* com.portal.board.bbs.BBSManageMapper.selectNoticeListForSort */
SELECT
	a.BBS_ID, a.NTT_ID, a.SORT_ORDR, a.PARNTSCTT_NO, a.NTT_NO, a.ANSWER_LC
  FROM LETTNBBS a
 WHERE a.BBS_ID = #{bbsId}
   AND a.SORT_ORDR = #{sortOrdr}
 ORDER BY a.SORT_ORDR DESC, a.NTT_NO ASC

/* com.portal.board.bbs.BBSManageMapper.selectBoardArticleList */ SELECT a.NTT_ID, a.NTT_SJ, a.NTT_CN, a.FRST_REGISTER_ID, IFNULL(b.USER_NM, a.NTCR_NM) AS FRST_REGISTER_NM, DATE_FORMAT(a.FRST_REGIST_PNTTM, '%Y-%m-%d') AS FRST_REGIST_PNTTM, a.RDCNT, a.PARNTSCTT_NO, a.ANSWER_AT, a.ANSWER_LC, a.USE_AT, a.ATCH_FILE_ID, a.BBS_ID, a.NTCE_BGNDE, a.NTCE_ENDDE FROM LETTNBBS a LEFT OUTER JOIN COMVNUSERMASTER b ON a.FRST_REGISTER_ID = b.ESNTL_ID WHERE a.BBS_ID = #{bbsId}
AND a.USE_AT = #{useAt}
AND a.NTT_SJ LIKE CONCAT('%', #{searchWrd}, '%')
AND a.NTT_CN LIKE CONCAT('%', #{searchWrd}, '%')
AND b.USER_NM LIKE CONCAT('%', #{searchWrd}, '%')
ORDER BY a.SORT_ORDR DESC, a.NTT_NO ASC LIMIT #{recordCountPerPage} OFFSET #{firstIndex}

/* com.portal.board.bbs.BBSManageMapper.selectBoardArticleListCnt */
SELECT COUNT(a.NTT_ID)
  FROM LETTNBBS a
  LEFT OUTER JOIN COMVNUSERMASTER b
    ON a.FRST_REGISTER_ID = b.ESNTL_ID
 WHERE a.BBS_ID = #{bbsId}

   AND a.USE_AT = #{useAt}


   AND a.NTT_SJ LIKE CONCAT('%', #{searchWrd}, '%')


   AND a.NTT_CN LIKE CONCAT('%', #{searchWrd}, '%')


   AND b.USER_NM LIKE CONCAT('%', #{searchWrd}, '%')

mapper.update:
/* com.portal.board.bbs.BBSManageMapper.deleteBoardArticle */
UPDATE LETTNBBS
   SET NTT_SJ          = #{nttSj},
       USE_AT          = 'N',
       LAST_UPDUSR_ID  = #{lastUpdusrId},
       LAST_UPDT_PNTTM = SYSDATE()
 WHERE BBS_ID = #{bbsId}
   AND NTT_ID = #{nttId}

mapper.select:
/* com.portal.board.bbs.BBSManageMapper.selectMaxInqireCo */
SELECT IFNULL(MAX(RDCNT), 0) + 1 AS RDCNT
  FROM LETTNBBS
 WHERE BBS_ID = #{bbsId}
   AND NTT_ID = #{nttId}

/* com.portal.board.bbs.BBSManageMapper.selectNoticeItemForSort */
SELECT IFNULL(MAX(NTT_NO), 0) + 1 AS NTT_NO
  FROM LETTNBBS
 WHERE BBS_ID = #{bbsId}
   AND SORT_ORDR = #{sortOrdr}
   AND NTT_ID = #{nttId}

mapper.update:
/* com.portal.board.bbs.BBSManageMapper.updateInqireCo */
UPDATE LETTNBBS
   SET RDCNT           = #{inqireCo},
       LAST_UPDUSR_ID  = #{lastUpdusrId},
       LAST_UPDT_PNTTM = SYSDATE()
 WHERE BBS_ID = #{bbsId}
   AND NTT_ID = #{nttId}

/* com.portal.board.bbs.BBSManageMapper.updateSortOrder */
UPDATE LETTNBBS
   SET NTT_NO = #{nttNo}
 WHERE NTT_ID = #{nttId}

