  FROM LETTNBBS
 WHERE BBS_ID = #{bbsId}
   AND NTT_ID = #{parnts}

mapper.update:
/* com.portal.board.bbs.BBSManageMapper.updateOtherNttNo */
UPDATE LETTNBBS
   SET NTT_NO = NTT_NO + 1
 WHERE BBS_ID = #{bbsId}
   AND SORT_ORDR = #{sortOrdr}

   AND NTT_NO > #{nttNo}

/* com.portal.board.bbs.BBSManageMapper.updateNttNo */
UPDATE LETTNBBS
   SET NTT_NO = #{nttNo}
 WHERE BBS_ID = #{bbsId}
   AND NTT_ID = #{nttId}
